struct NoLog { static void log(std::string_view) noexcept {} };
struct ConsoleLog { static void log(std::string_view m) { std::puts(m.data()); } };

template <class LogPolicy = NoLog>
class Worker {
public:
    void run() { LogPolicy::log("starting"); }   // no-op compiled away for NoLog
};
Worker<> quiet;                    // null behaviour fixed at compile time
Worker<ConsoleLog> noisy;          // real behaviour, still called unconditionally
